//! Onigmo's own test cases (`testpy.py`, about 1,200 of them) run against the
//! vendored build, UTF-8 only.
//!
//! The table in `cases.rs` is generated by `tools/gen_onigmo_suite.py`. This
//! file is the runner; it follows `xx()` of `testpy.py`, which calls
//! `onig_new` and then `onig_search`, `onig_search_gpos` or `onig_match`.
//!
//! Cases of the other encodings (UTF-16/32, EUC-JP, Shift_JIS) never reach the
//! table: the generator runs `main()` of `testpy.py` as if the encoding were
//! UTF-8, so the `if onig_encoding == ...` branches for other encodings are
//! skipped. We do not build those encodings (the editor decodes text first).

use crate::ffi::{self, Compiled, Syntax};

mod cases;

/// Bytes of a pattern or a text, in a form a `static` table can hold.
enum Bytes {
    Lit(&'static [u8]),
    /// `unit` repeated `count` times (testpy.py builds long inputs with `"a" * 2000`).
    Rep(&'static [u8], usize),
    Cat(&'static [Bytes]),
}

impl Bytes {
    fn to_vec(&self) -> Vec<u8> {
        match self {
            Self::Lit(data) => data.to_vec(),
            Self::Rep(unit, count) => unit.repeat(*count),
            Self::Cat(parts) => parts.iter().flat_map(Bytes::to_vec).collect(),
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum Kind {
    Forward,
    Backward,
    Match,
}

/// One call of `xx()` in `testpy.py`. Positions are byte offsets; `-1` means
/// "not given" (or the end of the text for `end`).
struct Case {
    pattern: Bytes,
    target: Bytes,
    from: isize,
    to: isize,
    mem: usize,
    not_match: bool,
    kind: Kind,
    gpos: isize,
    start: isize,
    end: isize,
    syn: Syntax,
    opt: i64,
    err: i64,
    execerr: i64,
}

impl Case {
    const DEFAULT: Case = Case {
        pattern: Bytes::Lit(b""),
        target: Bytes::Lit(b""),
        from: 0,
        to: 0,
        mem: 0,
        not_match: false,
        kind: Kind::Forward,
        gpos: -1,
        start: 0,
        end: -1,
        syn: Syntax::OnigmoDefault,
        opt: 0,
        err: 0,
        execerr: 0,
    };
}

enum Item {
    Case(Case),
    /// `onig_set_match_stack_limit_size` (process-wide).
    StackLimit(u32),
    /// `onig_set_parse_depth_limit` (process-wide).
    ParseDepthLimit(u32),
}

fn show(bytes: &[u8]) -> String {
    let text = String::from_utf8_lossy(bytes);
    text.chars().take(60).collect()
}

/// Runs one case; `Err` carries the reason it failed.
fn run(c: &Case) -> Result<(), String> {
    let opt = u32::try_from(c.opt).map_err(|_| "bad option".to_owned())?;
    let (pattern, target) = (c.pattern.to_vec(), c.target.to_vec());
    let compiled = match Compiled::new(&pattern, opt, c.syn) {
        Ok(compiled) if c.err == 0 => compiled,
        Ok(_) => return Err(format!("expected compile error {}, compiled fine", c.err)),
        Err(e) if i64::from(e.code) == c.err => return Ok(()),
        Err(e) => return Err(format!("compile error {}: {}", e.code, e.message)),
    };

    let len = target.len();
    let to_pos = |v: isize| usize::try_from(v).unwrap_or(len);
    let gpos = usize::try_from(c.gpos).ok();
    let result = match c.kind {
        Kind::Forward => compiled.search(&target, gpos, to_pos(c.start), to_pos(c.end), 0),
        // A backward search starts at `endpos` and scans down to `startpos`.
        Kind::Backward => compiled.search(&target, gpos, to_pos(c.end), to_pos(c.start), 0),
        Kind::Match => compiled.match_at(&target, to_pos(c.start), 0),
    };
    match result {
        Err(e) if i64::from(e.code) == c.execerr => Ok(()),
        Err(e) => Err(format!("search error {}: {}", e.code, e.message)),
        Ok(None) if c.not_match => Ok(()),
        Ok(None) => Err("no match".to_owned()),
        Ok(Some(_)) if c.not_match => Err("matched but should not".to_owned()),
        Ok(Some(groups)) => {
            // A group that did not take part reads as -1..-1 (ONIG_REGION_NOTPOS).
            let got = groups
                .get(c.mem)
                .copied()
                .flatten()
                .map_or((-1, -1), |(beg, end)| (beg as isize, end as isize));
            if got == (c.from, c.to) {
                Ok(())
            } else {
                Err(format!("expected {}-{}, got {got:?}", c.from, c.to))
            }
        }
    }
}

/// One test, not one per case: the stack and parse-depth limits are
/// process-wide and the cases change them in the middle.
#[test]
fn onigmo_testpy_utf8() {
    let _exclusive = crate::LIMITS_LOCK
        .write()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    let mut ran = 0usize;
    let mut failures = Vec::new();
    for item in cases::ITEMS {
        match item {
            Item::Case(c) => {
                ran += 1;
                if let Err(reason) = run(c) {
                    failures.push(format!(
                        "/{}/ on '{}': {reason}",
                        show(&c.pattern.to_vec()),
                        show(&c.target.to_vec())
                    ));
                }
            }
            Item::StackLimit(n) => ffi::set_match_stack_limit(*n),
            Item::ParseDepthLimit(n) => ffi::set_parse_depth_limit(*n),
        }
    }
    assert!(ran > 1100, "only {ran} cases were generated");
    assert!(
        failures.is_empty(),
        "{} of {ran} cases failed:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
